```", "content_sha256": "4cd827d98d0d48d6effd539906e0c4f25dc9c5abba21d44229010a96a0ae2f5a"}]}

{"method": "hybrid", "embedding_model": "intfloat/multilingual-e5-small", "chunks": [{"chunk_id": "delivery_days", "source": "kb/metrics.md", "content": "delivery_days 平均交付天数／配送时长
